from collections import defaultdict
import re
_DEBUG = 0

def WM_approx_Ham1_search(pattern, text):
	m = len(pattern)
	S_table = defaultdict(int)
	for (i, c) in enumerate(pattern):
		S_table[c] |= 1 << i
	R0 = 0
	R1 = 0
	mask = 1 << m - 1
	for (j, c) in enumerate(text):
		S = S_table[c]
		shR0 = R0 << 1 | 1
		R0 = shR0 & S
		R1 = (R1 << 1 | 1) & S | shR0
		if _DEBUG:
			print('j= %2d msk=%s S=%s R0=%s R1=%s' % tuple([j] + map(bitstr, [mask, S, R0, R1])))
		if R0 & mask:
			yield (0, j - m + 1)
		elif R1 & mask:
			yield (1, j - m + 1)
if _DEBUG:

	def bitstr(num, mlen=8):
		wstr = ''
		for i in xrange(mlen):
			if num & 1:
				wstr = '1' + wstr
			else:
				wstr = '0' + wstr
			num >>= 1
		return wstr

def Ham_dist(s1, s2):
	assert len(s1) == len(s2)
	return sum((c1 != c2 for (c1, c2) in zip(s1, s2)))

def long_check(pattern, text):
	m = len(pattern)
	for i in xrange(len(text) - m + 1):
		d = Ham_dist(pattern, text[i:i + m])
		if d < 2:
			yield (d, i)

def Paul_McGuire_regex(pattern, text):
	searchSeqREStr = '(' + pattern + ')|(' + ')|('.join((pattern[:i] + '[a-z]'.replace(c, '') + pattern[i + 1:] for (i, c) in enumerate(pattern))) + ')'
	searchSeqRE = re.compile(searchSeqREStr)
	for match in searchSeqRE.finditer(text):
		locn = match.start()
		dist = int(bool(match.lastindex - 1))
		yield (dist, locn)
t = int(input())
for i in range(t):
	(p, v) = input().split()
	r = []
	for l in list(WM_approx_Ham1_search(v, p)):
